+import { Component, EventEmitter, Output, inject } from '@angular/core';
+import { CommonModule } from '@angular/common';
+import { ReactiveFormsModule, FormBuilder, Validators, FormGroup } from '@angular/forms';
+import { LoginService } from './login.ser'; // <-- 1. Importação adicionada
+
+@Component({
+  selector: 'app-login',
+  standalone: true,
+  imports: [CommonModule, ReactiveFormsModule],
+  templateUrl: './login.html',
+  styleUrls: ['./login.css']
+})
+export class Login {
+  // Eventos para o componente Pai (Home) saber o que fazer
+  @Output() loginSuccess = new EventEmitter<void>();
+  @Output() goToSignup = new EventEmitter<void>();
+
+  private fb = inject(FormBuilder);
+  private loginService = inject(LoginService); // <-- 2. Serviço injetado
+  isLoading = false;
+
+  loginForm = this.fb.group({
+    email: ['', [Validators.required, Validators.email]],
+    password: ['', [Validators.required, Validators.minLength(6)]]
+  });
+
+  // Helpers de validação visual
+  isFieldInvalid(fieldName: string): boolean {
+    const field = this.loginForm.get(fieldName);
+    return !!(field && field.invalid && (field.dirty || field.touched));
+  }
+
+  isFieldValid(fieldName: string): boolean {
+    const field = this.loginForm.get(fieldName);
+    return !!(field && field.valid && (field.dirty || field.touched));
+  }
+
+  onSubmit() {
+    if (this.loginForm.valid) {
+      this.isLoading = true;
+      const payload = this.loginForm.value; // Pega o email e a senha
+
+      // <-- 3. Chamada API real (substituindo a simulação com setTimeout)
+      this.loginService.login(payload).subscribe({
+        
+        // Em caso de sucesso
+        next: (response) => {
+          console.log('Login bem-sucedido!', response);
+          this.isLoading = false;
+          // Emite o evento de sucesso para o pai (Home) redirecionar
+          this.loginSuccess.emit(); 
+          // **TODO:** Persistir dados do usuário/token aqui
+        },
+        
+        // Em caso de erro
+        error: (error) => {
+          console.error('Erro no Login:', error);
+          this.isLoading = false;
+          // **TODO:** Adicionar lógica para mostrar mensagem de erro (ex: credenciais inválidas) no template
+        },
+        
+        // Finaliza a subscrição
+        complete: () => {
+          console.log('Chamada de login concluída.');
+        }
+      });
+      
+    } else {
+      this.loginForm.markAllAsTouched();
+    }
+  }
+
+  onSignupClick() {
+    // Emite evento para trocar o card para Signup
+    this.goToSignup.emit();
+  }
+}
