import { Component, EventEmitter, Output, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, Validators } from '@angular/forms';
import { HttpClient } from '@angular/common/http';
import { LoginService } from '../../services/login';
import { FeedbackService } from '../../services/feedback.service';
import { Router } from '@angular/router';

@Component({
  selector: 'app-login',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './login.html',
  styleUrls: ['./login.css']
})
export class Login {
  // Evento para navegar de volta (simulando roteamento)
  @Output() navigateBack = new EventEmitter<void>();

  // Injeção moderna de dependência
  private fb = inject(FormBuilder);
  private http = inject(HttpClient);
  private loginService = inject(LoginService);
  private feedback = inject(FeedbackService);
  private router = inject(Router);

  isLoading = false;
  errorMessage = '';

  loginForm = this.fb.group({
    email: ['', [Validators.required, Validators.email]],
    password: ['', [Validators.required, Validators.minLength(6)]]
  });

  navigateToHome() {
    this.navigateBack.emit();
    this.router.navigate(['/']);
  }

  isFieldInvalid(fieldName: string): boolean {
    const field = this.loginForm.get(fieldName);
    return !!(field && field.invalid && (field.dirty || field.touched));
  }

  isFieldValid(fieldName: string): boolean {
    const field = this.loginForm.get(fieldName);
    return !!(field && field.valid && (field.dirty || field.touched));
  }

  onLogin() {
    if (this.loginForm.valid) {
      this.isLoading = true;
      this.errorMessage = '';
      
      const loginPayload = {
        email: this.loginForm.get('email')?.value,
        password: this.loginForm.get('password')?.value
      };

      // Chamada à API via LoginService
      this.loginService.login(loginPayload)
        .subscribe({
          next: (response) => {
            this.isLoading = false;
            console.log('Login realizado com sucesso!', response);
            
            // Armazenar dados do usuário se a API retornar
            if (response.user) {
              localStorage.setItem('userData', JSON.stringify(response.user));
            }

            // Persistir email utilizado no login para consumo em outras partes (Navbar)
            const emailVal = this.loginForm.get('email')?.value || '';
            localStorage.setItem('userEmail', String(emailVal));
            
            // Feedback visual de sucesso
            this.feedback.showSuccess('Login realizado com sucesso!', 'Sucesso');
            // Navegar para a área logada (AfterLogin dentro do layout)
            this.router.navigate(['/nav/home']);
          },
          error: (error) => {
            this.isLoading = false;
            console.error('Erro no login:', error);
            this.errorMessage = error.error?.mensagem || error.error?.message || 'Falha ao fazer login. Verifique suas credenciais.';
            this.feedback.showError(this.errorMessage);
          }
        });
    } else {
      this.loginForm.markAllAsTouched();
    }
  }
}
